public int jump(int[] nums) {
    int jumps = 0, curEnd = 0, farthest = 0;
    for (int i = 0; i < nums.length - 1; i++) {
        farthest = Math.max(farthest, i + nums[i]);
        if (i == curEnd) { jumps++; curEnd = farthest; }
    }
    return jumps;
}

public int canCompleteCircuit(int[] gas, int[] cost) {
    int total = 0, tank = 0, start = 0;
    for (int i = 0; i < gas.length; i++) {
        int diff = gas[i] - cost[i];
        total += diff;
        tank  += diff;
        if (tank < 0) { start = i + 1; tank = 0; }
    }
    return total >= 0 ? start : -1;
}

public int candy(int[] r) {
    int n = r.length;
    int[] c = new int[n];
    java.util.Arrays.fill(c, 1);
    for (int i = 1; i < n; i++)
        if (r[i] > r[i - 1]) c[i] = c[i - 1] + 1;
    for (int i = n - 2; i >= 0; i--)
        if (r[i] > r[i + 1]) c[i] = Math.max(c[i], c[i + 1] + 1);
    int sum = 0;
    for (int x : c) sum += x;
    return sum;
}

public int leastInterval(char[] tasks, int n) {
    int[] freq = new int[26];
    for (char t : tasks) freq[t - 'A']++;
    int maxFreq = 0;
    for (int f : freq) maxFreq = Math.max(maxFreq, f);
    int cntMax = 0;
    for (int f : freq) if (f == maxFreq) cntMax++;
    int frame = (maxFreq - 1) * (n + 1) + cntMax;
    return Math.max(frame, tasks.length);
}

public java.util.List<Integer> partitionLabels(String s) {
    int[] last = new int[26];
    for (int i = 0; i < s.length(); i++)
        last[s.charAt(i) - 'a'] = i;
    java.util.List<Integer> res = new java.util.ArrayList<>();
    int start = 0, end = 0;
    for (int i = 0; i < s.length(); i++) {
        end = Math.max(end, last[s.charAt(i) - 'a']);
        if (i == end) {
            res.add(i - start + 1);
            start = i + 1;
        }
    }
    return res;
}

public int minRefuelStops(int target, int startFuel, int[][] stations) {
    java.util.PriorityQueue<Integer> heap =
        new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
    long fuel = startFuel;
    int stops = 0, i = 0, n = stations.length;
    while (fuel < target) {
        while (i < n && stations[i][0] <= fuel) {
            heap.offer(stations[i][1]);
            i++;
        }
        if (heap.isEmpty()) return -1;
        fuel += heap.poll();
        stops++;
    }
    return stops;
}

public int scheduleCourse(int[][] courses) {
    java.util.Arrays.sort(courses, (a, b) -> a[1] - b[1]);
    java.util.PriorityQueue<Integer> heap =
        new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
    int time = 0;
    for (int[] c : courses) {
        time += c[0];
        heap.offer(c[0]);
        if (time > c[1]) time -= heap.poll();
    }
    return heap.size();
}

public int maxEvents(int[][] events) {
    java.util.Arrays.sort(events, (a, b) -> a[0] - b[0]);
    java.util.PriorityQueue<Integer> heap = new java.util.PriorityQueue<>();
    int i = 0, n = events.length, attended = 0, maxDay = 0;
    for (int[] e : events) maxDay = Math.max(maxDay, e[1]);
    for (int day = 1; day <= maxDay; day++) {
        while (i < n && events[i][0] == day) heap.offer(events[i++][1]);
        while (!heap.isEmpty() && heap.peek() < day) heap.poll();
        if (!heap.isEmpty()) { heap.poll(); attended++; }
    }
    return attended;
}

public int twoCitySchedCost(int[][] costs) {
    java.util.Arrays.sort(costs, (a, b) -> (a[0] - a[1]) - (b[0] - b[1]));
    int n = costs.length / 2, total = 0;
    for (int i = 0; i < n; i++) total += costs[i][0];
    for (int i = n; i < costs.length; i++) total += costs[i][1];
    return total;
}

public int videoStitching(int[][] clips, int time) {
    int[] maxReach = new int[time + 1];
    for (int[] c : clips)
        if (c[0] <= time) maxReach[c[0]] = Math.max(maxReach[c[0]], c[1]);

    int count = 0, curEnd = 0, farthest = 0;
    for (int i = 0; i <= time; i++) {
        if (i > farthest) return -1;
        if (i > curEnd) { count++; curEnd = farthest; }
        farthest = Math.max(farthest, maxReach[i]);
    }
    return count;
}

public String removeKdigits(String num, int k) {
    StringBuilder st = new StringBuilder();
    for (char c : num.toCharArray()) {
        while (k > 0 && st.length() > 0 && st.charAt(st.length() - 1) > c) {
            st.deleteCharAt(st.length() - 1);
            k--;
        }
        st.append(c);
    }
    st.setLength(st.length() - k);
    int i = 0;
    while (i < st.length() && st.charAt(i) == '0') i++;
    String res = st.substring(i);
    return res.isEmpty() ? "0" : res;
}

public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
    int n = profits.length;
    int[][] proj = new int[n][2];
    for (int i = 0; i < n; i++) { proj[i][0] = capital[i]; proj[i][1] = profits[i]; }
    java.util.Arrays.sort(proj, (a, b) -> a[0] - b[0]);
    java.util.PriorityQueue<Integer> heap =
        new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
    int i = 0;
    for (int round = 0; round < k; round++) {
        while (i < n && proj[i][0] <= w) heap.offer(proj[i++][1]);
        if (heap.isEmpty()) break;
        w += heap.poll();
    }
    return w;
}
